head.script:
// https://inswave01.atlassian.net/browse/WAEA-1505



// 담당 범위 : noResult 값별 편집 완료 처리 (propval 전 항목) + 완전 일치 시 미동작
//  - emptyItem / selectFirstOnEndEdit / selectSingleOnEnter 관련 항목은 column_P_noResult_2.xml
//  - 데이터 로드 / 메소드 설정과 valueNotInList 관련 항목은 column_P_noResult_3.xml
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > noResult]<br/>inputType='autoComplete' 인 Column 에서 사용자의 입력값과 일치하는 아이템이 없을 때 편집 완료 처리 방식을 설정합니다.",
    "validation" : [
        "previous 설정 시, 사용자의 입력값을 버리고 편집 전 Cell 값을 유지합니다.",
        "미설정 시, 사용자의 입력값을 버리고 편집 전 Cell 값을 유지합니다.",
        "clear 설정 시, 사용자의 입력값을 버리고 ''(Empty String) 으로 Cell 값을 설정합니다.",
        "clear 설정 시, chooseOption='true' 또는 allOption='true' 이면 아이템 목록의 첫번째 항목이 선택됩니다.",
        "noEnd 설정 시, Enter 키 입력 시 편집을 완료하지 않고 편집 모드를 유지합니다.",
        "noEnd 설정 시, Enter 키 입력이 아닌 포커스 이동 등으로 편집 완료 시 'previous' 로 동작합니다.",
        "useData 설정 시, 사용자의 입력값을 Label 과 Value 로 갖는 아이템을 목록에 추가합니다.",
        "useData 설정 시, Cell 값은 새로 추가된 아이템값으로 설정됩니다.",
        "keepValue 설정 시, 사용자의 입력값을 아이템 목록엔 추가하지 않고 Cell 값에만 반영합니다.",
        "first 설정 시, Enter 키 입력 시 표시된 아이템 목록의 첫번째 항목을 Cell 값에 설정합니다.",
        "first 설정 시, 표시된 아이템 목록이 없는 상태에서 Enter 키 입력 시 전체 아이템의 첫번째 항목이 Cell 값에 설정됩니다.",
        "first 설정 시, Enter 키 입력이 아닌 포커스 이동 등으로 편집 완료 시 'previous' 로 동작합니다.",
        "사용자의 입력값이 아이템 목록의 값과 완전히 일치하는 경우엔 noResult 속성이 동작하지 않고 해당 아이템이 Cell 값에 설정됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_noResult.setValue("previous");
    con_chooseOption.setValue("1");
    con_allOption.setValue("1");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - name : 안내 Column (readOnly) / city : 검증 대상 autoComplete Column (noResult / chooseOption / allOption = con 값)
//  - 아이템 : 서울(S), 부산(B), 대구(D), 대전(J) / Row 0 = S, Row 1 = B, Row 2 = D
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정 (gdl_boolean 은 getText() 로 '' / 'true' / 'false' 판단, 미설정 옵션은 속성 자체를 넣지 않는다)
    let cNoResult = con_noResult.getValue();
    let cChooseOption = con_chooseOption.getText();
    let cAllOption = con_allOption.getText();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 아이템 : 서울(S), 부산(B), 대구(D), 대전(J)\n[절차] city 셀 더블클릭 -> 입력값을 지우고 제주(목록 없음) / 대(대구, 대전 표시) / 부산(완전 일치) 입력 -> Enter 또는 Tab\n[확인] 편집 완료 시 출력되는 Cell 값, Enter 후 편집 입력창 유지 여부, 다른 Row 셀 편집 시 아이템 목록"', '', 'label1');

    let attrCol = '';
    if (cNoResult !== '') {
        attrCol += ' noResult="' + cNoResult + '"';
    }
    if (cChooseOption !== '') {
        attrCol += ' chooseOption="' + cChooseOption + '"';
    }
    if (cAllOption !== '') {
        attrCol += ' allOption="' + cAllOption + '"';
    }

    // dataList 생성 (body column id 와 동일한 컬럼 id 사용)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="city" name="city" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "홍길동", "city" : "S" },
        { "name" : "김철수", "city" : "B" },
        { "name" : "이영희", "city" : "D" }
    ], false);

    // 정적 아이템
    let strItems = '';
    strItems += '<w2:choices>';
    strItems += '<w2:item><w2:label>서울</w2:label><w2:value>S</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>부산</w2:label><w2:value>B</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>대구</w2:label><w2:value>D</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>대전</w2:label><w2:value>J</w2:value></w2:item>';
    strItems += '</w2:choices>';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:400px;height:250px;"'
        + ' ev:onafteredit="scwin.target1_onafteredit">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column1" value="name"></w2:column>';
    strTarget += '<w2:column width="230" style="" inputType="text" id="column2" value="city (autoComplete)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="name" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="230" style="" inputType="autoComplete" id="city" value=""' + attrCol + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 편집 완료 시 Cell 값 / 표시값 출력
//  - validation 1 ~ 4, 6 ~ 13 판정 출력 (validation 5 는 Enter 후 출력 없음 + 편집 입력창 유지로 판정)
scwin.target1_onafteredit = function (rowIndex, colIndex, value) {
    wf_body_bottom.getObj("scwin").setReturnValue("편집 완료 Row " + rowIndex + " -> Cell 값 : '" + target1.getCellData(rowIndex, "city") + "' (표시 : '" + target1.getCellDisplayData(rowIndex, "city") + "')");
};
